### RAJA version

```cpp
// vector_add_raja.cu
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <cstdlib>

int main()
{
    constexpr int N = 1<<20;          // 1M elements
    size_t sz = N*sizeof(float);

    // Host data
    float *h_A = (float*)malloc(sz);
    float *h_B = (float*)malloc(sz);
    float *h_C = (float*)malloc(sz);

    for (int i=0;i<N;i++) { h_A[i] = i; h_B[i] = 2*i; }

    // Device data
    float *d_A, *d_B, *d_C;
    RAJA::cuda_malloc(&d_A, sz);
    RAJA::cuda_malloc(&d_B, sz);
    RAJA::cuda_malloc(&d_C, sz);

    RAJA::cuda_memcpy(d_A, h_A, sz, RAJA::cudaMemcpyHostToDevice);
    RAJA::cuda_memcpy(d_B, h_B, sz, RAJA::cudaMemcpyHostToDevice);

