### RAJA version

```cpp
// stencil_raja.cu
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <cstdlib>

int main()
{
    constexpr int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    // Host arrays
    float *h_in  = (float*)malloc(sz);
    float *h_out = (float*)malloc(sz);
    for (int j=0;j<ny;j++)
      for (int i=0;i<nx;i++)
        h_in[j*nx+i] = static_cast<float>(i+j);

    // Device arrays
    float *d_in, *d_out;
    RAJA::cuda_malloc(&d_in, sz);
    RAJA::cuda_malloc(&d_out, sz);
    RAJA::cuda_memcpy(d_in, h_in, sz, RAJA::cudaMemcpyHostToDevice);

    // RAJA 2‑D kernel
    RAJA::kernel<RAJA::cuda_exec<16,16,RAJA::cuda_async>>(
        RAJA::make_tuple(
            RAJA::RangeSegment(1, nx-1),   // i
            RAJA::RangeSegment(1, ny-1)    // j
        ),
        [=] RAJA_DEVICE (int i, int j) {
            int idx = j*nx + i;
            d_out[idx] = 0.25f * ( d_in[idx-1] + d_in[idx+1]
                                 + d_in[idx-nx] + d_in[idx+nx] );
        });

    // Wait for GPU
    RAJA::cuda_device_sync();

    // Copy back
    RAJA::cuda_memcpy(h_out, d_out, sz, RAJA::cudaMemcpyDeviceToHost);
    std::cout << "out[256,256]=" << h_out[256*nx+256] << std::endl;

    RAJA::cuda_free(d_in); RAJA::cuda_free(d_out);
    free(h_in); free(h_out);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 -std=c++17 stencil_raja.cu -o stencil_raja
./stencil_raja
```

> **Key RAJA concepts used**  
> * `RAJA::kernel` is a generic multi‑dimensional loop nest.  
> * `RAJA::make_tuple` builds the loop extents.  
> * `RAJA::RangeSegment(start, end)` defines a 1‑D range (inclusive start, exclusive end).  
> * `RAJA::cuda_exec<16,16,RAJA::cuda_async>` creates a 2‑D CUDA grid with 16×16 threads per block.  
> * The lambda receives the loop indices (`i`, `j`) and can use device pointers directly.  

