## 2.  2‑D 5‑point stencil (heat diffusion)

### CUDA version

```cpp
// stencil.cu
#include <cuda_runtime.h>
#include <stdio.h>

__global__ void stencil(const float *in, float *out, int nx, int ny)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;   // x‑index
    int j = blockIdx.y * blockDim.y + threadIdx.y;   // y‑index

    if (i>0 && i<nx-1 && j>0 && j<ny-1) {
        int idx = j*nx + i;
        out[idx] = 0.25f * ( in[idx-1] + in[idx+1]
                           + in[idx-nx] + in[idx+nx] );
    }
}

int main()
{
    const int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    float *h_in  = (float*)malloc(sz);
    float *h_out = (float*)malloc(sz);
    for (int j=0;j<ny;j++)
      for (int i=0;i<nx;i++)
        h_in[j*nx+i] = (float)(i+j);

    float *d_in, *d_out;
    cudaMalloc(&d_in, sz); cudaMalloc(&d_out, sz);
    cudaMemcpy(d_in, h_in, sz, cudaMemcpyHostToDevice);

    dim3 threads(16,16);
    dim3 blocks((nx+threads.x-1)/threads.x,
                (ny+threads.y-1)/threads.y);

    stencil<<<blocks,threads>>>(d_in, d_out, nx, ny);
    cudaDeviceSynchronize();

    cudaMemcpy(h_out, d_out, sz, cudaMemcpyDeviceToHost);
    printf("out[256,256]=%f\n", h_out[256*nx+256]);

    cudaFree(d_in); cudaFree(d_out);
    free(h_in); free(h_out);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 stencil.cu -o stencil
./stencil
```

---

### RAJA version

```cpp
// stencil_raja.cu
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <cstdlib>

int main()
{
    constexpr int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    // Host arrays
    float *h_in  = (float*)malloc(sz);
    float *h_out = (float*)malloc(sz);
    for (int j=0;j<ny;j++)
      for (int i=0;i<nx;i++)
        h_in[j*nx+i] = static_cast<float>(i+j);

    // Device arrays
    float *d_in, *d_out;
    RAJA::cuda_malloc(&d_in, sz);
    RAJA::cuda_malloc(&d_out, sz);
    RAJA::cuda_memcpy(d_in, h_in, sz, RAJA::cudaMemcpyHostToDevice);

    // RAJA 2‑D kernel
    RAJA::kernel<RAJA::cuda_exec<16,16,RAJA::cuda_async>>(
        RAJA::make_tuple(
            RAJA::RangeSegment(1, nx-1),   // i
            RAJA::RangeSegment(1, ny-1)    // j
        ),
        [=] RAJA_DEVICE (int i, int j) {
            int idx = j*nx + i;
            d_out[idx] = 0.25f * ( d_in[idx-1] + d_in[idx+1]
                                 + d_in[idx-nx] + d_in[idx+nx] );
        });

    // Wait for GPU
    RAJA::cuda_device_sync();

    // Copy back
    RAJA::cuda_memcpy(h_out, d_out, sz, RAJA::cudaMemcpyDeviceToHost);
    std::cout << "out[256,256]=" << h_out[256*nx+256] << std::endl;

    RAJA::cuda_free(d_in); RAJA::cuda_free(d_out);
    free(h_in); free(h_out);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 -std=c++17 stencil_raja.cu -o stencil_raja
./stencil_raja
```

> **Key RAJA concepts used**  
> * `RAJA::kernel` is a generic multi‑dimensional loop nest.  
> * `RAJA::make_tuple` builds the loop extents.  
> * `RAJA::RangeSegment(start, end)` defines a 1‑D range (inclusive start, exclusive end).  
> * `RAJA::cuda_exec<16,16,RAJA::cuda_async>` creates a 2‑D CUDA grid with 16×16 threads per block.  
> * The lambda receives the loop indices (`i`, `j`) and can use device pointers directly.  

