    int M = 1024;
    int N = 1024;
    int P = 1024;
    float *A, *B, *C;
    cudaMallocManaged(&A, M * P * sizeof(float));
    cudaMallocManaged(&B, P * N * sizeof(float));
    cudaMallocManaged(&C, M * N * sizeof(float));

    // Initialize data
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < P; j++) {
            A[i * P + j] = i + j;
        }
    }
    for (int i = 0; i < P; i++) {
        for (int j = 0; j < N; j++) {
            B[i * N + j] = i + j;
        }
    }

    RAJA::forall<RAJA::cuda_exec<256, 256>>(RAJA::RangeSegment(0, M), RAJA::RangeSegment(0, N), [=] RAJA_HOST_DEVICE(int row, int col) {
        float sum = 0.0f;
        for (int k = 0; k < P; k++) {
            sum += A[row * P + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    });

    // Synchronize
    cudaDeviceSynchronize();

    // Print result
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            printf("%f ", C[i * N + j]);
        }
        printf("\n");
    }

    return 0;
}
```

